-- mistri store layout: experiments, postgres, version 1. Generated by scripts/store-layouts.mjs; never edit by hand.
SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;
CREATE SCHEMA mistri;
CREATE FUNCTION mistri.experiment_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN RAISE EXCEPTION 'Experiment metadata, facts and evidence are append-only.'; END$$;
SET default_tablespace = '';
SET default_table_access_method = heap;
CREATE TABLE mistri.experiment_binding (
    singleton integer NOT NULL,
    version integer NOT NULL,
    suite_id text NOT NULL COLLATE pg_catalog."C",
    deployment_id text NOT NULL COLLATE pg_catalog."C",
    CONSTRAINT experiment_binding_deployment_id_check CHECK ((octet_length(deployment_id) <= 128)),
    CONSTRAINT experiment_binding_singleton_check CHECK ((singleton = 1)),
    CONSTRAINT experiment_binding_suite_id_check CHECK ((octet_length(suite_id) <= 128)),
    CONSTRAINT experiment_binding_version_check CHECK ((version = 1))
);
CREATE TABLE mistri.experiment_conversions (
    epoch_key text NOT NULL COLLATE pg_catalog."C",
    source_key text NOT NULL COLLATE pg_catalog."C",
    metric_id text NOT NULL COLLATE pg_catalog."C",
    unit_key text NOT NULL COLLATE pg_catalog."C",
    occurred_at bigint NOT NULL,
    received_at bigint NOT NULL,
    CONSTRAINT experiment_conversions_epoch_key_check CHECK ((octet_length(epoch_key) <= 128)),
    CONSTRAINT experiment_conversions_metric_id_check CHECK ((octet_length(metric_id) <= 128)),
    CONSTRAINT experiment_conversions_occurred_at_check CHECK (((occurred_at >= 0) AND (occurred_at <= '9007199254740991'::bigint))),
    CONSTRAINT experiment_conversions_received_at_check CHECK (((received_at >= 0) AND (received_at <= '9007199254740991'::bigint))),
    CONSTRAINT experiment_conversions_source_key_check CHECK ((octet_length(source_key) <= 128)),
    CONSTRAINT experiment_conversions_unit_key_check CHECK ((octet_length(unit_key) <= 128))
);
CREATE TABLE mistri.experiment_decisions (
    epoch_key text NOT NULL COLLATE pg_catalog."C",
    decision_id text NOT NULL COLLATE pg_catalog."C",
    document text NOT NULL,
    CONSTRAINT experiment_decisions_decision_id_check CHECK ((octet_length(decision_id) <= 128)),
    CONSTRAINT experiment_decisions_document_check CHECK ((octet_length(document) <= 1048576)),
    CONSTRAINT experiment_decisions_epoch_key_check CHECK ((octet_length(epoch_key) <= 128))
);
CREATE TABLE mistri.experiment_epochs (
    epoch_key text NOT NULL COLLATE pg_catalog."C",
    fingerprint text NOT NULL COLLATE pg_catalog."C",
    declaration text NOT NULL,
    registered_at bigint NOT NULL,
    CONSTRAINT experiment_epochs_declaration_check CHECK ((octet_length(declaration) <= 1048576)),
    CONSTRAINT experiment_epochs_epoch_key_check CHECK ((octet_length(epoch_key) <= 128)),
    CONSTRAINT experiment_epochs_fingerprint_check CHECK ((octet_length(fingerprint) <= 128)),
    CONSTRAINT experiment_epochs_registered_at_check CHECK (((registered_at >= 0) AND (registered_at <= '9007199254740991'::bigint)))
);
CREATE TABLE mistri.experiment_exposure_coverage (
    epoch_key text NOT NULL COLLATE pg_catalog."C",
    started_at bigint NOT NULL,
    CONSTRAINT experiment_exposure_coverage_epoch_key_check CHECK ((octet_length(epoch_key) <= 128)),
    CONSTRAINT experiment_exposure_coverage_started_at_check CHECK (((started_at >= 0) AND (started_at <= '9007199254740991'::bigint)))
);
CREATE TABLE mistri.experiment_exposure_obligations (
    epoch_key text NOT NULL COLLATE pg_catalog."C",
    unit_key text NOT NULL COLLATE pg_catalog."C",
    arm_id text NOT NULL COLLATE pg_catalog."C",
    CONSTRAINT experiment_exposure_obligations_arm_id_check CHECK ((octet_length(arm_id) <= 128)),
    CONSTRAINT experiment_exposure_obligations_epoch_key_check CHECK ((octet_length(epoch_key) <= 128)),
    CONSTRAINT experiment_exposure_obligations_unit_key_check CHECK ((octet_length(unit_key) <= 128))
);
CREATE TABLE mistri.experiment_exposures (
    epoch_key text NOT NULL COLLATE pg_catalog."C",
    unit_key text NOT NULL COLLATE pg_catalog."C",
    arm_id text NOT NULL COLLATE pg_catalog."C",
    used_at bigint NOT NULL,
    received_at bigint NOT NULL,
    CONSTRAINT experiment_exposures_arm_id_check CHECK ((octet_length(arm_id) <= 128)),
    CONSTRAINT experiment_exposures_epoch_key_check CHECK ((octet_length(epoch_key) <= 128)),
    CONSTRAINT experiment_exposures_received_at_check CHECK (((received_at >= 0) AND (received_at <= '9007199254740991'::bigint))),
    CONSTRAINT experiment_exposures_unit_key_check CHECK ((octet_length(unit_key) <= 128)),
    CONSTRAINT experiment_exposures_used_at_check CHECK (((used_at >= 0) AND (used_at <= '9007199254740991'::bigint)))
);
CREATE TABLE mistri.experiment_progress (
    epoch_key text NOT NULL COLLATE pg_catalog."C",
    data_revision bigint NOT NULL,
    evidence_revision bigint NOT NULL,
    exposures bigint NOT NULL,
    conversions bigint NOT NULL,
    CONSTRAINT experiment_progress_conversions_check CHECK (((conversions >= 0) AND (conversions <= '9007199254740991'::bigint))),
    CONSTRAINT experiment_progress_data_revision_check CHECK (((data_revision >= 0) AND (data_revision <= '9007199254740991'::bigint))),
    CONSTRAINT experiment_progress_epoch_key_check CHECK ((octet_length(epoch_key) <= 128)),
    CONSTRAINT experiment_progress_evidence_revision_check CHECK (((evidence_revision >= 0) AND (evidence_revision <= '9007199254740991'::bigint))),
    CONSTRAINT experiment_progress_exposures_check CHECK (((exposures >= 0) AND (exposures <= '9007199254740991'::bigint)))
);
CREATE TABLE mistri.experiment_results (
    epoch_key text NOT NULL COLLATE pg_catalog."C",
    revision bigint NOT NULL,
    document text NOT NULL,
    CONSTRAINT experiment_results_document_check CHECK ((octet_length(document) <= 1048576)),
    CONSTRAINT experiment_results_epoch_key_check CHECK ((octet_length(epoch_key) <= 128)),
    CONSTRAINT experiment_results_revision_check CHECK (((revision >= 0) AND (revision <= '9007199254740991'::bigint)))
);
INSERT INTO mistri.experiment_binding (singleton, version, suite_id, deployment_id) VALUES (1, 1, 'layout-suite', 'layout-deployment');
ALTER TABLE ONLY mistri.experiment_binding
    ADD CONSTRAINT experiment_binding_pkey PRIMARY KEY (singleton);
ALTER TABLE ONLY mistri.experiment_conversions
    ADD CONSTRAINT experiment_conversions_pkey PRIMARY KEY (epoch_key, source_key, metric_id);
ALTER TABLE ONLY mistri.experiment_decisions
    ADD CONSTRAINT experiment_decisions_pkey PRIMARY KEY (epoch_key, decision_id);
ALTER TABLE ONLY mistri.experiment_epochs
    ADD CONSTRAINT experiment_epochs_pkey PRIMARY KEY (epoch_key);
ALTER TABLE ONLY mistri.experiment_exposure_coverage
    ADD CONSTRAINT experiment_exposure_coverage_pkey PRIMARY KEY (epoch_key);
ALTER TABLE ONLY mistri.experiment_exposure_obligations
    ADD CONSTRAINT experiment_exposure_obligations_pkey PRIMARY KEY (epoch_key, unit_key);
ALTER TABLE ONLY mistri.experiment_exposures
    ADD CONSTRAINT experiment_exposures_pkey PRIMARY KEY (epoch_key, unit_key);
ALTER TABLE ONLY mistri.experiment_progress
    ADD CONSTRAINT experiment_progress_pkey PRIMARY KEY (epoch_key);
ALTER TABLE ONLY mistri.experiment_results
    ADD CONSTRAINT experiment_results_pkey PRIMARY KEY (epoch_key, revision);
CREATE INDEX experiment_conversions_unit ON mistri.experiment_conversions USING btree (epoch_key, unit_key, metric_id, occurred_at);
CREATE INDEX experiment_exposures_maturity ON mistri.experiment_exposures USING btree (epoch_key, used_at, arm_id);
CREATE TRIGGER experiment_binding_immutable BEFORE DELETE OR UPDATE OR TRUNCATE ON mistri.experiment_binding FOR EACH STATEMENT EXECUTE FUNCTION mistri.experiment_immutable();
CREATE TRIGGER experiment_conversions_immutable BEFORE DELETE OR UPDATE OR TRUNCATE ON mistri.experiment_conversions FOR EACH STATEMENT EXECUTE FUNCTION mistri.experiment_immutable();
