CREATE TRIGGER experiment_epochs_immutable BEFORE DELETE OR UPDATE OR TRUNCATE ON mistri.experiment_epochs FOR EACH STATEMENT EXECUTE FUNCTION mistri.experiment_immutable();
CREATE TRIGGER experiment_exposure_coverage_immutable BEFORE DELETE OR UPDATE OR TRUNCATE ON mistri.experiment_exposure_coverage FOR EACH STATEMENT EXECUTE FUNCTION mistri.experiment_immutable();
CREATE TRIGGER experiment_exposure_obligations_immutable BEFORE DELETE OR UPDATE OR TRUNCATE ON mistri.experiment_exposure_obligations FOR EACH STATEMENT EXECUTE FUNCTION mistri.experiment_immutable();
CREATE TRIGGER experiment_results_immutable BEFORE DELETE OR UPDATE OR TRUNCATE ON mistri.experiment_results FOR EACH STATEMENT EXECUTE FUNCTION mistri.experiment_immutable();
